def calculate_sequence(N):
    a = [0] * (N + 1)

    # Base cases
    if N >= 1:
        a[1] = 1
    if N >= 2:
        a[2] = 1

    # Recurrence relation for n >= 3
    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

        # We must ensure that the indices are valid (i.e., a_{n-1} >= 1 and n - a_{n-1} >= 1)
        # Since a_n are positive integers for n >= 1, a_{n-1} >= 1.
        # Also, for n >= 3, a_{n-1} >= 1, so n - a_{n-1} <= n-1 < n.
        # We need to check if n - a_{n-1} is at least 1.

        a_n_minus_1 = a[n-1]

        if a_n_minus_1 >= n:
            # This case implies a_{n-1} >= n, meaning a_{n-1} is too large 
            # for the second term a_{n - a_{n-1}} to be defined in the sequence up to N.
            # Given the nature of the sequence so far, this is unlikely for small N,
            # but it's a safety check. Let's assume for now that a_n grows slower than n.
            # If it happens, the problem formulation might break down for this N.
            # Based on manual calculation, this won't happen up to N=20.
            pass 

        # Check for index validity for the first term a_{a_{n-1}}
        if a_n_minus_1 <= N:
            term1 = a[a_n_minus_1]
        else:
            # If a_{n-1} is larger than N, we cannot compute it.
            # For the task of finding the first 20 terms, this won't happen.
            term1 = None 

        # Check for index validity for the second term a_{n - a_{n-1}}
        index2 = n - a_n_minus_1
        if index2 >= 1 and index2 <= N:
            term2 = a[index2]
        else:
            term2 = None

        if term1 is not None and term2 is not None:
            a[n] = term1 + term2
        else:
            # Should not happen for N=20
            a[n] = -1 # Sentinel for error

    return a[1:]

