def calculate_a(N):
    a = {1: 1, 2: 1}
    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        term1_index = a[n-1]
        term2_index = n - a[n-1]

        # We must ensure the indices are within the calculated range
        if term1_index not in a or term2_index not in a:
            raise ValueError(f"Index out of bounds for n={n}. a[{term1_index}] or a[{term2_index}] not computed.")

        a[n] = a[term1_index] + a[term2_index]
    return a

